import{_ as e,o as a,c as i,ag as r}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"EmakiForge","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/index.md","filePath":"en/modules/forge/index.md","lastUpdated":null}'),o={name:"en/modules/forge/index.md"};function d(n,t,s,l,c,p){return a(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="emakiforge" tabindex="-1">EmakiForge <a class="header-anchor" href="#emakiforge" aria-label="Permalink to &quot;EmakiForge&quot;">​</a></h1><p>EmakiForge runs the forging flow. Players place target equipment, blueprints, and materials; the module checks recipe requirements, capacity, and conditions, then modifies the target item or creates a new result.</p><h2 id="module-facts" tabindex="-1">Module facts <a class="header-anchor" href="#module-facts" aria-label="Permalink to &quot;Module facts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>4.6.4</code></td></tr><tr><td>Main command</td><td><code>/emakiforge</code></td></tr><tr><td>Aliases</td><td><code>/eforge</code>, <code>/ef</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependency</td><td>EmakiAttribute, EmakiItem, PlaceholderAPI</td></tr><tr><td>Main permissions</td><td><code>emakiforge.use</code>, <code>emakiforge.book</code>, <code>emakiforge.reload</code>, <code>emakiforge.debug</code>, <code>emakiforge.admin</code></td></tr></tbody></table><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Description</th></tr></thead><tbody><tr><td>Blueprint</td><td>Controls whether a player can use a forging recipe.</td></tr><tr><td>Material</td><td>Resources the player adds to influence success, quality, or final attributes.</td></tr><tr><td>Recipe</td><td>Defines input requirements, capacity, conditions, results, and actions.</td></tr><tr><td>Capacity</td><td>Limits the sum of <code>capacity_cost</code> across inserted materials.</td></tr><tr><td>Quality</td><td>Deterministic weighted outcome tier, optionally with pity.</td></tr><tr><td>Recipe book</td><td>GUI used to inspect available recipes.</td></tr></tbody></table><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to &quot;Default runtime folder&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiForge/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   └── example_recipe.yml</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── forge_gui.yml</span></span>
<span class="line"><span>│   └── recipe_book.yml</span></span>
<span class="line"><span>├── lang/</span></span>
<span class="line"><span>│   ├── zh_CN.yml</span></span>
<span class="line"><span>│   └── en_US.yml</span></span>
<span class="line"><span>└── data/</span></span></code></pre></div><p>Start with <code>recipes/</code>. That folder defines forging inputs, capacity, conditions, results, and actions. <code>data/</code> is maintained by <code>PlayerDataStore</code> and holds one <code>&lt;uuid&gt;.yml</code> per player with craft counters and pity counters.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Content</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Forging, recipe book, reload, list, and debug commands.</td></tr><tr><td><a href="./recipes.html">Recipes</a></td><td>Inputs, blueprints, results, actions, and recipe matching.</td></tr><tr><td><a href="./materials.html">Materials</a></td><td>Material contribution, capacity, quality modifiers, and effect writes.</td></tr><tr><td><a href="./quality.html">Quality</a></td><td>Quality pools, pity, item metadata, and deterministic logic.</td></tr><tr><td><a href="./history.html">Forge History</a></td><td>Player forging data, autosave, and troubleshooting.</td></tr><tr><td><a href="./gui.html">GUI</a></td><td>Forge UI and recipe book templates.</td></tr><tr><td><a href="./audit.html">Audit</a></td><td>Forge audit data and material signature on result items.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Refresh actions registered by Forge.</td></tr><tr><td><a href="./api.html">API</a></td><td>The <code>EmakiForgeApi</code> static facade.</td></tr><tr><td><a href="./events.html">Events</a></td><td><code>ForgeStartEvent</code>, <code>ForgeCompletedEvent</code>.</td></tr></tbody></table><h2 id="typical-forging-flow" tabindex="-1">Typical forging flow <a class="header-anchor" href="#typical-forging-flow" aria-label="Permalink to &quot;Typical forging flow&quot;">​</a></h2><ol><li>Open the forge GUI with <code>/ef forge</code>.</li><li>Place a blueprint in the blueprint slots; Forge matches the recipe by blueprint item source.</li><li>Place materials in the required and optional material slots.</li><li>Check recipe, condition, capacity, and material count.</li><li>Click the confirm slot to run <code>actions.pre</code>.</li><li>Resolve deterministic quality and pity from the player, recipe, and material fingerprint.</li><li>Create the primary item from <code>result.success.outputs</code> and attach the forge layer snapshot.</li><li>Run <code>result.success.actions</code> → <code>actions.success</code> → quality actions; on failure run <code>actions.failure</code>.</li><li>The CoreLib item assembly service rebuilds the item presentation.</li><li>With EmakiAttribute installed, <code>ea_attribute</code> material effects are written to the structured PDC attribute layer.</li></ol><h2 id="relation-with-attribute" tabindex="-1">Relation with Attribute <a class="header-anchor" href="#relation-with-attribute" aria-label="Permalink to &quot;Relation with Attribute&quot;">​</a></h2><p>Forge can run basic forging without Attribute. The <code>ea_attribute</code> material effect requires EmakiAttribute: attributes are written through the EmakiAttribute authoritative API into a structured PDC layer, so the numbers participate in real combat calculation instead of only appearing in lore.</p><p>When EmakiAttribute is absent, Forge takes a no-op path: forging still completes, it simply does not write attribute payloads, and no error is raised.</p>`,16)])])}const m=e(o,[["render",d]]);export{u as __pageData,m as default};
